const root=path.resolve('.'),dir=path.join(root,'research/nevir-system');
const files=['翻后教学系统_统一总纲.md',...fs.readdirSync(dir).filter(n=>n.endsWith('.md')).map(n=>'research/nevir-system/'+n)];
assert.ok(files.length>=9,'Expected master and at least eight specifications');
let links=0;
for(const file of files){
 const body=fs.readFileSync(path.join(root,file),'utf8');
 assert.ok(body.length>500);assert.equal((body.match(/^```/gm)||[]).length%2,0);
 for(const match of body.matchAll(/\]\(([^)]+)\)/g)){
  const target=match[1].replace(/^<|>$/g,'');if(/^https?:/.test(target)||target.startsWith('#'))continue;
  const resolved=path.resolve(path.dirname(path.join(root,file)),target.split('#')[0]);
  if(resolved!==path.join(dir,'validation.json'))assert.ok(fs.existsSync(resolved),'Broken local link '+file+' '+target);links++;
 }
}
