for(const name of expectedMetadataNames){
 const meta=documentMetadata.documents[name],body=fs.readFileSync(path.join(dir,name),'utf8');
 for(const key of ['parentDocument','routeNode','evidenceLevel','opensChildren','returnTo','currentStatus'])assert.ok(meta[key]!==undefined,'Missing metadata '+name+' '+key);
 assert.ok(body.includes('"parentDocument"')&&body.includes('"currentStatus"'),'Metadata not embedded in '+name);
 assert.ok(body.includes(meta.parentDocument)&&body.includes(meta.routeNode)&&body.includes(meta.currentStatus),'Embedded metadata mismatch '+name);
 for(const child of meta.opensChildren)assert.ok(fs.existsSync(path.join(dir,child))||fs.existsSync(path.join(root,child)),'Metadata child missing '+name+' '+child);
 assert.ok(fs.existsSync(path.join(dir,meta.parentDocument))||fs.existsSync(path.join(root,meta.parentDocument)),'Metadata parent missing '+name);
 assert.ok(fs.existsSync(path.join(dir,meta.returnTo))||fs.existsSync(path.join(root,meta.returnTo)),'Metadata return target missing '+name);
}
