for(const n of flow.nodes){
 if(n.parent){assert.ok(ids.has(n.parent));assert.ok(ids.has(n.returnTo));const seen=new Set([n.id]);let p=n.parent;while(p){assert.ok(!seen.has(p),'Cyclic hierarchy');seen.add(p);p=flow.nodes.find(n=>n.id===p).parent;}}
 else assert.ok(flow.roots.includes(n.id));
}
