const states=new Set(flow.states),pairs=new Set();
for(const [a,event,b]of flow.transitions){assert.ok(states.has(a)&&states.has(b));assert.ok(!flow.terminals.includes(a));assert.ok(!pairs.has(a+':'+event));pairs.add(a+':'+event);}
const reached=new Set(['hero_free','wait_initial']);let changed=true;while(changed){changed=false;for(const[a,,b]of flow.transitions)if(reached.has(a)&&!reached.has(b)){reached.add(b);changed=true;}}
assert.equal(reached.size,states.size,'Unreachable documented state');
function route(start,events,end){let state=start;for(const event of events){const row=flow.transitions.find(([a,e])=>a===state&&e===event);assert.ok(row,'Missing transition '+state+' '+event);state=row[2];}assert.equal(state,end);return{start,events,end};}
const routes=[
 route('hero_free',['hero_check_passes','villain_check','deal_next_street','villain_acts_first','villain_bet','hero_call_closes','river_actions_complete'],'showdown'),
 route('hero_free',['hero_bet','villain_raise','hero_reraise_if_legal','villain_reraise','hero_fold'],'end_hero_fold'),
 route('wait_initial',['villain_bet','hero_raise','villain_fold'],'end_villain_fold'),
 route('hero_free',['hero_bet','villain_call_allin','deal_remaining_to_showdown'],'showdown'),
 route('hero_facing_raise',['hero_call_allin','deal_remaining_to_showdown'],'showdown')
];
// Independent checks of the numerical examples from the current decision point.
const cs=s=>s.split(' ').map(card),board=cs('Ks 7h 2d 3c 9h'),hero=cs('Qs Qc');
const groups=[{cards:cs('6s 6h'),w:.4,calls:[0,0]},{cards:cs('Js Jd'),w:.4,calls:[1,0]},{cards:cs('Kh Kd'),w:.2,calls:[1,1]}];
for(const g of groups)assertCards([...board,...hero,...g.cards]);
const eq=g=>{const c=compare(evaluate([...board,...hero]),evaluate([...board,...g.cards]));return c>0?1:c<0?0:.5;};
const ev=b=>groups.reduce((s,g)=>{const e=eq(g),c=b?g.calls[b===5?0:1]:0;return s+g.w*(b?(1-c)*10+c*(e*(10+b)-(1-e)*b):e*10);},0);
assert.deepEqual([ev(0),ev(5),ev(10)],[8,9,6]);
assert.equal(5/(10+5+5),.25);assert.equal(10/(10+5+15+10),.25);assert.equal(20/(20+10+30+20),.25);
assert.ok(.2*15-.8*5<0);assert.ok(.4*15-.6*5>0);
