const rangeExample=JSON.parse(fs.readFileSync(path.join(dir,'starting-range-example.json'),'utf8'));
const sourceChart=charts.find(c=>c.id===rangeExample.source.chart),known=new Set([...rangeExample.context.board,...rangeExample.context.heroHole]);
assertCards([...known].map(card));
// Independently count legal combinations by rank/suit availability, rather than reuse pair enumeration.
const suits=['s','h','d','c'];let rawCombos=0,rawMass=0,legalCombos=0,legalMass=0;
for(const [h,entry]of Object.entries(sourceChart.hands)){
 const frequency=entry.action.call||0;if(!frequency)continue;
 const pair=h[0]===h[1],same=h.endsWith('s');
 const a=suits.filter(s=>!known.has(h[0]+s)),b=suits.filter(s=>!known.has(h[1]+s));
 const matched=a.filter(s=>b.includes(s)).length;
 const n=pair?a.length*(a.length-1)/2:same?matched:a.length*b.length-matched;
 const before=pair?6:same?4:12;
 rawCombos+=before;rawMass+=before*frequency;legalCombos+=n;legalMass+=n*frequency;
 const rows=rangeExample.combos.filter(c=>c.handClass===h);assert.equal(rows.length,n);
 for(const c of rows){assert.equal(c.mass,frequency);assert.ok(Math.abs(c.weight-frequency/rangeExample.afterKnownCards.totalMass)<1e-12);assertCards([...known,...c.cards].map(card));}
}
assert.deepEqual([rawCombos,rawMass,legalCombos,legalMass],[402,328,306,252]);
assert.equal(rangeExample.combos.length,legalCombos);
assert.deepEqual(rangeExample.context.postflopObservation,[]);
assert.equal(rangeExample.context.state,'Flop dealt, before BB first postflop action');
const bridge=JSON.parse(fs.readFileSync(path.join(dir,'input-bridge-evidence.json'),'utf8'));
assert.deepEqual([bridge.baseline.positiveCombos,bridge.baseline.mass],[legalCombos,legalMass]);
// Count each hand class after the new card, independently of the generator's combo filtering.
const knownTurn=new Set([...known,bridge.physicalTurnOnly.turn]);let turnCombos=0,turnMass=0;
for(const [h,entry]of Object.entries(sourceChart.hands)){
 const f=entry.action.call||0;if(!f)continue;
 const a=suits.filter(s=>!knownTurn.has(h[0]+s)),b=suits.filter(s=>!knownTurn.has(h[1]+s));
 const matching=a.filter(s=>b.includes(s)).length;
 const n=h[0]===h[1]?a.length*(a.length-1)/2:h.endsWith('s')?matching:a.length*b.length-matching;
 turnCombos+=n;turnMass+=n*f;
}
assert.deepEqual([turnCombos,turnMass],[300,246.5]);
assert.deepEqual([bridge.physicalTurnOnly.remainingCombos,bridge.physicalTurnOnly.remainingMass],[turnCombos,turnMass]);
assert.deepEqual([bridge.physicalTurnOnly.blockedCombos,bridge.physicalTurnOnly.blockedMass],[legalCombos-turnCombos,legalMass-turnMass]);
