 const expected=x.equity.map(e=>e*(x.potIncludingBet+x.toCall)-x.toCall);
 for(let i=0;i<2;i++)assert.ok(Math.abs(expected[i]-x.evBounds[i])<1e-10);
 assert.equal(x.result,expected[0]>0?'call_over_fold':expected[1]<0?'fold_over_call':'not_identified');
