const walk=JSON.parse(fs.readFileSync(path.join(dir,'full-walkthrough-reference.json'),'utf8'));
const query=new URL(walk.reference.solutionLink).searchParams;
assert.equal(query.get('gmff_rake'),'NL500');assert.equal(query.get('depth'),'100');
assert.equal(query.get('board'),walk.reference.boardFromLink.join(''));
