// Independent class-size calculation: rank/suit availability, not 1326-pair enumeration.
function classCounts(h,knownIds){
 const a=suits.filter(s=>!knownIds.includes(h[0]+s)),b=suits.filter(s=>!knownIds.includes(h[1]+s));
 const same=a.filter(s=>b.includes(s)).length,off=a.length*b.length-same;
 const raw=h.length===2?same+off:h.endsWith('s')?same:off;
 const mass=h.length===2?same*(blockerChart.hands[h+'s'].action.call||0)+off*(blockerChart.hands[h+'o'].action.call||0):raw*(blockerChart.hands[h].action.call||0);
 return{raw,mass};
}
