for(const example of Object.values(sizeEvidence.examples)){
 const total=Object.values(example.weights).reduce((a,b)=>a+b,0);
 for(const action of example.actions){
  let ledgerEV=0;
  for(const g of sizeEvidence.groups){
   const startStack=sizeEvidence.context.activeStackBB,bet=action.bet,pot=sizeEvidence.context.potBB;
   const calls=action.id==='small'?(example.responseOverrides[g.id]?.callsSmall??g.callsSmall):action.id==='large'?(example.responseOverrides[g.id]?.callsLarge??g.callsLarge):false;
   const finalStack=action.id==='check'?startStack+pot*g.equity:!calls?startStack-bet+bet+pot:startStack-bet+(pot+2*bet)*g.equity;
   ledgerEV+=example.weights[g.id]*(finalStack-startStack)/total;
  }
  assert.ok(Math.abs(ledgerEV-action.evBB)<1e-10);
 }
}
