// A second finite-family calculation uses explicit payoff coefficients and integer
// cross products; it does not reuse the generator's per-group EV decomposition.
const sizeBestCounts={};let sizeModels=0,sizeLowerEquityCounterexamples=0;
for(let j=0;j<=3;j++)for(let lo=0;lo<=3;lo++)for(let k=0;k<=3;k++)for(let kk=0;kk<=3;kk++)for(let t=0;t<=3;t++)for(let a=0;a<=3;a++){
 if(j+lo+k+kk+t+a===0)continue;sizeModels++;
 const nums=[20*(j+lo+a)+10*t,30*(j+lo)-10*(k+kk)+10*t+20*a,40*j+20*lo+20*k-20*kk+10*t+20*a];
 const max=Math.max(...nums),set=['check','small','large'].filter((_,i)=>nums[i]===max).join('|');
 sizeBestCounts[set]=(sizeBestCounts[set]||0)+1;
 const smallCalled=j+lo+k+kk+t,largeCalled=j+kk+t;
 if(smallCalled&&largeCalled&&(2*j+t)*smallCalled<(2*(j+lo)+t)*largeCalled&&nums[2]>nums[1])sizeLowerEquityCounterexamples++;
}
assert.equal(sizeModels,4095);assert.equal(sizeEvidence.exhaustiveFamily.models,sizeModels);
assert.deepEqual(sizeEvidence.exhaustiveFamily.bestSetCounts,sizeBestCounts);
