const defenseWinningSets={KK:new Set(['4s','5s','6s','8s','9s','Ts','Js']),KJ:new Set(['2s','3s','4s','5s','6s','8s','9s','Ts','Js','Ah','Ad','Ac'])};
defenseWinningSets.JT=new Set(defenseDeck.filter(id=>![...defenseKnown,'Js','Ts'].includes(id)&&!['J','T'].includes(id[0])));
