// Independent closed-form counts: five spades yield additional payment from JT;
// 33 JT winning rivers are surrendered at the actual shared information sets.
const defenseExpectedEV={pressure:[0,-7/44,-30,-5217/154],more_bluffs:[0,35/88,-1689/88,-1689/88],fold_to_raise:[0,-7/44,295/154,-5217/154],fold_to_shove:[0,-7/44,-30,2225/154]};
const defenseBest={pressure:['fold'],more_bluffs:['call'],fold_to_raise:['raise_to_30'],fold_to_shove:['jam_to_90']};
const defenseNear=(a,b)=>assert.ok(Math.abs(a-b)<1e-9,`Defense mismatch ${a} vs ${b}`);
for(const p of defenseTree.profiles){
 assert.deepEqual(p.actions.map(a=>a.id),['fold','call','raise_to_30','jam_to_90']);
 p.actions.forEach((a,i)=>defenseNear(a.evBB,defenseExpectedEV[p.id][i]));assert.deepEqual(p.best,defenseBest[p.id]);
 const total=p.weights.reduce((a,b)=>a+b,0);assert.equal(total,p.totalWeight);
 defenseNear(p.showdownEquity,p.weights.reduce((s,w,i)=>s+w*defenseWinningSets[defenseTree.holdings[i].id].size,0)/(44*total));
 defenseNear(p.freeShowdownCallEVBB,42*p.showdownEquity-10.5);
 for(const [tree,likelihood]of [[p.flatContinuation,[1,1,1]],[p.smallRaise.callContinuation,p.smallResponse.map(r=>r.call)]]){
  let expectedTreeEV=0,expectedProbability=0;
  const invested=tree.turnInvestedBB,pot=21+2*invested,bet=pot/2,stack=90-invested;
  assert.deepEqual([tree.potBB,tree.eachStackBB,tree.opponentRiverBetBB],[pot,stack,bet]);
  assert.equal(pot+2*stack+399,600);assert.ok(bet<=stack);
  for(const state of tree.informationSets){
   let betMass=0,winMass=0,foldContribution=0,callContribution=0,checkContribution=0,dealMass=0;
   const hidden={};
   defenseTree.holdings.forEach((h,i)=>{
    if(h.hole.includes(state.river))return;
    const mass=p.weights[i]*likelihood[i]/(total*44);dealMass+=mass;
    const wins=defenseWinningSets[h.id].has(state.river)?1:0;
    const spade=state.river[1]==='s',rank=state.river[0];
    const bets=h.id==='KK'?(!spade||['2','3'].includes(rank)):h.id==='KJ'?(!spade&&rank!=='A'):true;
    if(bets){betMass+=mass;winMass+=mass*wins;foldContribution-=invested*mass;callContribution+=mass*((pot+2*bet)*wins-invested-bet);if(mass)hidden[h.id]=mass;}
    else checkContribution+=mass*(pot*wins-invested);
   });
   defenseNear(state.dealJointProbability,dealMass);defenseNear(state.betJointProbability,betMass);
   defenseNear(state.foldEVContribution,foldContribution);defenseNear(state.callEVContribution,callContribution);defenseNear(state.checkEVContribution,checkContribution);
   if(betMass){
    defenseNear(state.equityOnObservedBet,winMass/betMass);
    for(const [id,mass]of Object.entries(hidden))defenseNear(state.posteriorOnObservedBet[id],mass/betMass);
    const expected=Math.abs(callContribution-foldContribution)<1e-12?'tie':callContribution>foldContribution?'call':'fold';assert.equal(state.chosen,expected);
   }else assert.equal(state.chosen,null);
   expectedTreeEV+=checkContribution+Math.max(foldContribution,callContribution);expectedProbability+=dealMass;
  }
  defenseNear(tree.evBB,expectedTreeEV);defenseNear(tree.branchProbability,expectedProbability);
  if(tree.branchProbability)defenseNear(tree.conditionalEVBB,tree.evBB/tree.branchProbability);else assert.equal(tree.conditionalEVBB,null);
  assert.ok(tree.forbiddenInformationAdvantageBB>=0);
 }
}
