assert.equal(roleEvidence.allPhysicalHoldings.length,49*48/2);
const independentRoleCounts={},roleKeys=new Set(),j95Ranks=[11,9,5];
const directStraightRankMap={KQ:['T'],KT:['Q'],QT:['8','K'],Q8:['T'],T8:['7','Q'],T7:['8'],'87':['6','T'],'86':['7'],'76':['8']};
for(const r of roleEvidence.allPhysicalHoldings){
 assert.deepEqual(r.board,['Js','9d','5d']);assertCards([...r.board,...r.hole].map(card));
 const key=[...r.hole].sort().join('');assert.ok(!roleKeys.has(key));roleKeys.add(key);
 const ranks=r.hole.map(id=>card(id).rank),pocket=ranks[0]===ranks[1],matched=ranks.filter(rank=>j95Ranks.includes(rank));
 let role,value;
 if(pocket){
  if(j95Ranks.includes(ranks[0])){role='set';value=[3,ranks[0],...j95Ranks.filter(rank=>rank!==ranks[0])];}
  else{const rank=ranks[0];role=rank>11?'pocket_above_board':rank>9?'pocket_between_top_middle':rank>5?'pocket_between_middle_bottom':'pocket_below_board';value=[1,rank,...j95Ranks];}
 }else if(matched.length===2){role='two_pair';value=[2,Math.max(...matched),Math.min(...matched),j95Ranks.find(rank=>!matched.includes(rank))];}
 else if(matched.length===1){const rank=matched[0];role=rank===11?'top_pair':rank===9?'middle_pair':'bottom_pair';value=[1,rank,...[...j95Ranks,...ranks].filter(n=>n!==rank).sort((a,b)=>b-a)];}
 else{role='high_card';value=[0,...[...j95Ranks,...ranks].sort((a,b)=>b-a)];}
 assert.equal(r.madeRole,role);assert.deepEqual(r.madeValue,value);independentRoleCounts[role]=(independentRoleCounts[role]||0)+1;
 const rankClass=[...r.hole].sort((a,b)=>card(b).rank-card(a).rank).map(id=>id[0]).join('');
 const expectedStraight=new Set(defenseDeck.filter(id=>(directStraightRankMap[rankClass]||[]).includes(id[0])&&![...r.board,...r.hole].includes(id)));
 assert.deepEqual(new Set(r.draw.nominalStraightOuts),expectedStraight);
 const diamondCount=r.hole.filter(id=>id[1]==='d').length;
 const expectedFlush=new Set(diamondCount===2?defenseDeck.filter(id=>id[1]==='d'&&![...r.board,...r.hole].includes(id)):[]);
 assert.deepEqual(new Set(r.draw.nominalFlushOuts),expectedFlush);
 const expectedBackdoor=['s','h','d','c'].filter(s=>[...r.board,...r.hole].filter(id=>id[1]===s).length===3);
 assert.deepEqual(r.draw.backdoorFlushSuits,expectedBackdoor);
 assert.equal(r.draw.hasDirectDraw,expectedStraight.size>0||expectedFlush.size>0);
 assert.equal(r.draw.madeAndDirect,value[0]>=1&&(expectedStraight.size>0||expectedFlush.size>0));
}
